package com.example.proyectolp.service;
import java.math.BigDecimal;import java.math.RoundingMode;import java.time.LocalDate;
public final class CreditRules {public static final int COP_PER_CREDIT=2000;private static final BigDecimal MILESTONE=BigDecimal.valueOf(20000);private static final BigDecimal MIN_GOAL=BigDecimal.valueOf(60000);private CreditRules(){}public static int habit(boolean completed,LocalDate date,LocalDate today){return completed&&today.equals(date)?1:0;}public static int task(boolean hasProject){return hasProject?1:3;}public static int stage(){return 1;}public static int goalTotal(BigDecimal target){if(target.compareTo(MIN_GOAL)<0)return 0;return target.divide(MILESTONE,0,RoundingMode.CEILING).intValueExact();}public static int crossedGoalMilestones(BigDecimal target,BigDecimal oldAmount,BigDecimal newAmount){return target.compareTo(MIN_GOAL)<0?0:crossedSavingsMilestones(target,oldAmount,newAmount);}public static int crossedSavingsMilestones(BigDecimal target,BigDecimal oldAmount,BigDecimal newAmount){if(newAmount.compareTo(oldAmount)<=0)return 0;int count=0;int milestones=target.divide(MILESTONE,0,RoundingMode.FLOOR).intValue();for(int k=1;k<=milestones;k++)if(oldAmount.compareTo(MILESTONE.multiply(BigDecimal.valueOf(k)))<0&&newAmount.compareTo(MILESTONE.multiply(BigDecimal.valueOf(k)))>=0)count++;if(target.remainder(MILESTONE).signum()!=0&&oldAmount.compareTo(target)<0&&newAmount.compareTo(target)>=0)count++;return count;}public static int goalMilestoneNumber(BigDecimal target,BigDecimal oldAmount,BigDecimal newAmount,int ordinal){int n=0,max=target.divide(MILESTONE,0,RoundingMode.FLOOR).intValue();for(int k=1;k<=max;k++)if(oldAmount.compareTo(MILESTONE.multiply(BigDecimal.valueOf(k)))<0&&newAmount.compareTo(MILESTONE.multiply(BigDecimal.valueOf(k)))>=0&&++n==ordinal)return k;if(target.remainder(MILESTONE).signum()!=0&&oldAmount.compareTo(target)<0&&newAmount.compareTo(target)>=0&&++n==ordinal)return max+1;return ordinal;}public static int penaltyDivisor(int streak){return streak<=10?2:streak<=30?3:4;}public static int penalizedBalance(int balance,int divisor){return Math.floorDiv(balance,divisor);}public static int penaltyDelta(int balance,int divisor){return balance==0?0:penalizedBalance(balance,divisor)-balance;}public static String habitKey(long id,LocalDate date){return "habit:"+id+":"+date;}public static String taskKey(long id){return "task:"+id;}public static String stageKey(long id){return "stage:"+id;}public static String goalKey(long id,int milestone){return "goal:"+id+":m"+milestone;}}
